record.field:
result = env["crm.lead"].action_sync_coins_voyageurs_google_sheet()
action = {
    "type": "ir.actions.client",
    "tag": "display_notification",
    "params": {
        "title": "Import voyageurs CM",
        "message": "Importés %(imported)s — incomplets %(incomplete)s — doublons skippés %(duplicates_skipped)s" % {
            "imported": result.get("imported", 0),
            "incomplete": result.get("incomplete", 0),
            "duplicates_skipped": result.get("duplicates_skipped", 0),
        } if result.get("ok") else result.get("error", "erreur"),
        "type": "success" if result.get("ok") else "danger",
        "sticky": True,
    },
}
